const chainsaw: Item = {
  id: "saw-01",
  name: "Chainsaw, 35 cm bar",
  category: "garden",
  safety_class: "C",
  deposit_cents: 6000,
  status: "in",
};
const inducted: Member = { ...member, inductions: ["C"] };

test("a member without the C induction cannot take the chainsaw", () => {
  expect(canBorrow(member, chainsaw).ok).toBe(false);
});

test("a member with the C induction can take the chainsaw", () => {
  expect(canBorrow(inducted, chainsaw)).toEqual({ ok: true });
});

test("the refusal for a missing induction names the chainsaw", () => {
  const decision = canBorrow(member, chainsaw);
  expect(decision.ok === false && decision.reason.includes(chainsaw.name)).toBe(true);
});

test("a class-B tool needs no induction", () => {
  expect(canBorrow(member, { ...ladder, safety_class: "B" })).toEqual({ ok: true });
});

test("an inducted member cannot take a chainsaw that is out or in repair", () => {
  expect(canBorrow(inducted, { ...chainsaw, status: "out" }).ok).toBe(false);
  expect(canBorrow(inducted, { ...chainsaw, status: "repair" }).ok).toBe(false);
});
EOF
